class RangeFreqQuery(arr:IntArray){private val positions=HashMap<Int,MutableList<Int>>();init{for(i in arr.indices)positions.getOrPut(arr[i]){mutableListOf()}.add(i)}private fun lower(values:List<Int>,target:Int):Int{var left=0;var right=values.size;while(left<right){val middle=(left+right)/2;if(values[middle]<target)left=middle+1 else right=middle};return left}private fun upper(values:List<Int>,target:Int):Int{var left=0;var right=values.size;while(left<right){val middle=(left+right)/2;if(values[middle]<=target)left=middle+1 else right=middle};return left}fun query(left:Int,right:Int,value:Int):Int{val values=positions[value]?:emptyList();return upper(values,right)-lower(values,left)}}
